 "turns": [
  {
   "id": "M1:T41",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'redundancy' and asks about it."
  },
  {
   "id": "M1:T42",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "All communication shall be based on the use of standard communication protocols, where retry procedures are applied (a form of software redundancy) as part of the protocol.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T43",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'user constraints' and asks about it."
  },
  {
   "id": "M1:T44",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": ".There should be no restrictions imposed by the software on users. Only policy decisions (permissions, access privileges, etc.) should prevent any user from accessing any part of the Gemini system from any local or remote station.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T45",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": ".There should be no restrictions imposed by the software on users. Only policy decisions (permissions, access privileges, etc.) should prevent any user from accessing any part of the Gemini system from any local or remote station.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T46",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T47",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'software constraints' and asks about it."
  },
  {
   "id": "M1:T48",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "All Gemini subsystem packages should include as part of the software both a simulator module for inclusion in the virtual telescope (see Design constraints, below), and user interface modules for the user interface environments that the subsystem will be operating in. The interfaces required of these user interface modules are described in Section 3.3 on page 3-6.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T49",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "All Gemini software is to be fully documented, internally with appropriate comments, and external documentation. External documentation must include Unix-style man pages.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T50",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'data flow' and asks about it."
  },
  {
   "id": "M1:T51",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Detector data must be acquired and stored in the most effective way technology will allow; effectiveness should be evaluated in terms of cost, space requirements, longevity, and speed.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T52",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "However, there must be at least two copies - one to secure data as acquired and one to do assessment of data quality on-line (this last copy preferably on removable media).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T53",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'data flow'."
  },
  {
   "id": "M1:T54",
   "speaker": "Client",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T55",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'format od data acquisition' and asks about it."
  },
  {
   "id": "M1:T56",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "There might, however, be cases (for example, infrared detectors) where fast preprocessing is needed and where, therefore, raw data will not be stored as such, but in a preprocessed format.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T57",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "There might, however, be cases (for example, infrared detectors) where fast preprocessing is needed and where, therefore, raw data will not be stored as such, but in a preprocessed format.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T58",
   "speaker": "EndUser",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T59",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'other information flow' and asks about it."
  },
  {
   "id": "M1:T60",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Other astronomical information such as that coming from sky field monitors, autoguider cameras and sky monitoring devices such as cloud and seeing monitors shall also be capable of being available.",
     "role": "statement"
    }
   ]
  }
 ]
